const SOURCES = ['repo-status', 'gmail'];
const STALE_HOURS = 72;
const MAX_REFS = 30;
const TITLE_MAX = 200;
const EXCERPT_MAX = 280;
const SUMMARY_MAX = 200;
const URL_MAX = 2048;
const BODY_MAX_BYTES = 48 * 1024;
const KIND = { github_pr: 'pull_request', github_issue: 'issue', gmail: 'mail' };
const LABEL = { pull_request: 'pull request', issue: 'issue', mail: 'mail', other: 'other' };

const rows = $input.all().map(i => i.json).filter(r => r.id != null);
const nowMs = Date.now();
const day = $now.toFormat('yyyy-LL-dd');

function parse(text) { try { return JSON.parse(text) || {}; } catch (e) { return {}; } }
function clip(s, max) { const t = String(s || '').replace(/\s+/g, ' ').trim(); return t.length > max ? t.slice(0, max - 1) + '…' : t; }
function iso(value, fallback) { const t = Date.parse(value); if (Number.isFinite(t)) return new Date(t).toISOString(); const f = Date.parse(fallback); return new Date(Number.isFinite(f) ? f : Date.now()).toISOString(); }
function utf8Bytes(s) { return encodeURIComponent(s).replace(/%[0-9A-F]{2}/g, 'x').length; }

const pending = rows.filter(r => r.status === 'pending').sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt));

const refs = [];
const counts = {};
const seen = new Set();
for (const row of pending) {
  const p = parse(row.payload);
  const kind = KIND[p.source] || 'other';
  const url = p.url || (p.source === 'gmail' && p.thread_id ? 'https://mail.google.com/mail/#inbox/' + p.thread_id : '');
  if (seen.has(url)) continue;
  if (url) seen.add(url);
  counts[kind] = (counts[kind] || 0) + 1;
  if (!/^https?:\/\//.test(url) || url.length > URL_MAX || refs.length >= MAX_REFS) continue;
  refs.push({ kind, title: clip(p.title || p.subject || row.key, TITLE_MAX), url, at: iso(p.updated_at || p.date, row.createdAt), excerpt: clip(p.snippet || '', EXCERPT_MAX) });
}

const oldest = pending.length ? pending[pending.length - 1].createdAt : null;
const since = oldest ? oldest.slice(0, 16).replace('T', ' ') : $now.minus({ days: 1 }).toFormat('yyyy-LL-dd HH:mm');
const parts = Object.entries(counts).map(([kind, n]) => n + ' ' + LABEL[kind] + (n === 1 ? '' : 's'));
const summary = clip((parts.length ? parts.join(', ') : 'nothing new') + ' since ' + since, SUMMARY_MAX);

const sources = SOURCES.map(name => {
  const stamps = rows.filter(r => r.source === name).map(r => Date.parse(r.createdAt)).filter(Number.isFinite);
  if (!stamps.length) return { name, status: 'stale' };
  const newest = Math.max(...stamps);
  return { name, status: nowMs - newest <= STALE_HOURS * 3600000 ? 'ok' : 'stale', last_ok: new Date(newest).toISOString() };
});

const envelope = { source: 'n8n', event_type: 'daily_briefing', delivery: 'immediate', event_id: 'daily-briefing:' + day, occurred_at: nowMs };
function render() { return JSON.stringify({ signals: [{ skill: 'yui-daily-briefing', summary, sources, refs }], envelope }); }
let body = render();
while (utf8Bytes(body) > BODY_MAX_BYTES && refs.length) { refs.pop(); body = render(); }

return [{ json: { body, posted_ids: pending.map(r => r.id), ref_count: refs.length, pending_count: pending.length } }];
